### Re-verifying authentication inside inline Server Actions in app/admin/page.tsx

Source: https://github.com/vercel/next.js/blob/canary/docs/01-app/02-guides/data-security.mdx

Page-level authentication checks do not protect Server Actions. Re-verify the session with auth() directly within the Server Action to prevent unauthorized execution via direct POST requests.

```tsx
import { auth } from '@/lib/auth'
import { redirect } from 'next/navigation'

export default async function AdminPage() {
  const session = await auth()
  if (!session?.user?.isAdmin) {
    redirect('/login')
  }

  return (
    <form
      action={async () => {
        'use server'
        const session = await auth()
        if (!session?.user?.isAdmin) {
          throw new Error('Unauthorized')
        }
        await db.record.deleteMany()
      }}
    >
      <button>Delete Records</button>
    </form>
  )
}
```

