### Authenticate and authorize a Server Action before deleting a post

Source: https://github.com/vercel/next.js/blob/canary/docs/01-app/02-guides/server-actions.mdx

Use this pattern for destructive operations like deletes. It checks the session and ownership before performing the database mutation, throwing errors for unauthorized or forbidden requests.

```ts
'use server'

import { auth } from '@/lib/auth'

export async function deletePost(postId: string) {
  const session = await auth()
  if (!session?.user) throw new Error('Unauthorized')
  if (!(await canDelete(session.user, postId))) throw new Error('Forbidden')

  await db.post.delete({ where: { id: postId } })
}
```

